from fastapi import FastAPI
from pydantic import BaseModel
import torch
import torch.nn as nn

class TinyModel(nn.Module):
    def __init__(self):
        super().__init__()
        self.fc = nn.Linear(10, 5)
    def forward(self, x): return self.fc(x)

app = FastAPI()
# 加载模型
model = TinyModel()
model.eval()

class Input(BaseModel):
    features: list[float]

# 推理端点
@app.post('/predict')
def predict(inp: Input):
    x = torch.tensor(inp.features).unsqueeze(0)
    with torch.no_grad():
        out = model(x)
    return {'prediction': out[0].tolist()}

# 运行: uvicorn main:app

